263→// ---------------------------------------------------------------------------
264→// Structured integration staging (Phase 26 SM1-SM9)
265→// ---------------------------------------------------------------------------
266→
267→const CONFLICT_MARKER = /(?:<{7,}|\|{7,}|={7,}|>{7,})/;
268→
269→function integrationRoot(repoRoot) { return join(repoRoot, '.baton', 'integrate'); }
270→
271→export async function removeStructuredIntegration(repoRoot, stage) {
272→  const dir = typeof stage === 'string' ? stage : stage?.stagePath;
273→  if (typeof dir === 'string' && dir.length > 0) {
274→    try { sh('git', ['worktree', 'remove', '--force', dir], repoRoot); } catch { rmSync(dir, { recursive: true, force: true }); }
275→  }
276→  try { sh('git', ['worktree', 'prune'], repoRoot); } catch { /* best effort */ }
277→  const root = integrationRoot(repoRoot);
278→  try { if (existsSync(root) && readdirSync(root).length === 0) rmSync(root, { recursive: true, force: true }); } catch { /* best effort */ }
279→}
280→
281→export async function stageStructuredIntegration(repoRoot, taskId, resultSha, opts = {}) {
282→  ensureBatonExcluded(repoRoot);
283→  if (!isClean(repoRoot)) throw mergeError('structured integration requires a clean main checkout', 'structured_main_dirty');
284→  let rightSha;
285→  try { rightSha = sh('git', ['rev-parse', '--verify', `${resultSha}^{commit}`], repoRoot); }
286→  catch (error) { throw mergeError('structured integration result is not a commit', 'structured_invalid_result', error); }
287→  const beforeSha = sh('git', ['rev-parse', 'HEAD'], repoRoot);
288→  try { sh('git', ['merge-base', '--is-ancestor', rightSha, beforeSha], repoRoot); throw mergeError('structured integration result is already contained by main', 'structured_already_integrated'); }
289→  catch (error) { if (error?.code === 'structured_already_integrated') throw error; }
290→  const mergeBaseSha = sh('git', ['merge-base', beforeSha, rightSha], repoRoot);
291→  const root = integrationRoot(repoRoot); mkdirSync(root, { recursive: true });
292→  const stagePath = join(root, `${taskId}-${randomBytes(4).toString('hex')}`);
293→  try { sh('git', ['worktree', 'add', '--detach', stagePath, beforeSha], repoRoot); }
294→  catch (error) { throw mergeError('structured integration stage could not be created', 'structured_stage_failed', error); }
295→  const classes = []; const resolutions = [];
296→  try {
297→    let mergeClean = true;
298→    try { gitFile(['-c', 'core.hooksPath=/dev/null', '-c', 'merge.conflictStyle=diff3', 'merge', '--no-verify', '--no-commit', '--no-ff', rightSha], stagePath, { encoding: 'utf8', stdio: 'pipe' }); }
299→    catch { mergeClean = false; }
300→    const unmergedRaw = gitFile(['diff', '--name-only', '--diff-filter=U', '-z'], stagePath, { encoding: 'utf8' });
301→    const conflictedPaths = unmergedRaw.split('\0').filter(Boolean);
302→    if (mergeClean) classes.push({ path: null, class: 'clean_textual' });
303→    else {
304→      if (conflictedPaths.length === 0) throw mergeError('Git merge failed without resolvable text conflicts', 'structured_merge_failed');
305→      if (!opts.resolver || typeof opts.resolver.resolve !== 'function') throw mergeError('structured merge resolver is unavailable', 'structured_tool_unavailable');
306→      if (!Number.isSafeInteger(opts.resolver.maxFileBytes) || opts.resolver.maxFileBytes <= 0) throw mergeError('structured resolver lacks a deployment-derived file ceiling', 'structured_policy_invalid');
307→      const realStagePath = realpathSync(stagePath);
308→      for (const relativePath of conflictedPaths) {
309→        const absolutePath = pathResolve(stagePath, relativePath); const within = pathRelative(stagePath, absolutePath);
310→        if (within === '..' || within.startsWith(`..${sep}`) || isAbsolute(within) || !existsSync(absolutePath) || !lstatSync(absolutePath).isFile()) throw mergeError(`unsupported structured conflict path: ${relativePath}`, 'structured_unsupported_path');
311→        const realConflictPath = realpathSync(absolutePath); const realWithin = pathRelative(realStagePath, realConflictPath);
312→        if (realWithin === '..' || realWithin.startsWith(`..${sep}`) || isAbsolute(realWithin)) throw mergeError(`structured conflict escapes stage: ${relativePath}`, 'structured_unsupported_path');
313→        const conflict = readFileSync(absolutePath); if (conflict.includes(0)) throw mergeError(`structured conflict is binary: ${relativePath}`, 'structured_binary_conflict');
314→        if (conflict.byteLength > opts.resolver.maxFileBytes) throw mergeError(`structured conflict exceeds file budget: ${relativePath}`, 'structured_file_too_large');
315→        const isolatedRoot = realpathSync(mkdtempSync(join(tmpdir(), 'baton-structured-conflict-'))); const isolatedName = basename(relativePath); const isolatedPath = join(isolatedRoot, isolatedName);
316→        let resolution; let merged;
317→        try {
318→          writeFileSync(isolatedPath, conflict, { mode: 0o600 });
319→          resolution = await opts.resolver.resolve({ cwd: isolatedRoot, relativePath: isolatedName, absolutePath: isolatedPath });
320→          if (resolution?.status === 'resolved') {
321→            if (!existsSync(isolatedPath) || !lstatSync(isolatedPath).isFile()) throw mergeError(`structured resolver replaced the candidate path: ${relativePath}`, 'structured_unsupported_path');
322→            merged = readFileSync(isolatedPath); if (merged.byteLength > opts.resolver.maxFileBytes) throw mergeError(`structured resolution exceeds file budget: ${relativePath}`, 'structured_file_too_large');
323→            if (merged.includes(0)) throw mergeError(`structured resolution is binary: ${relativePath}`, 'structured_binary_conflict');
324→          }
325→        } finally { rmSync(isolatedRoot, { recursive: true, force: true }); }
326→        resolutions.push({ path: relativePath, ...resolution });
327→        if (resolution?.status === 'parse_fallback') throw mergeError(`structured resolver fell back for ${relativePath}`, 'structured_parse_fallback');
328→        if (resolution?.status !== 'resolved') throw mergeError(`structured resolver did not resolve ${relativePath}`, resolution?.status === 'unknown' ? 'structured_tool_unknown' : 'structured_unresolved');
329→        const mergedText = new TextDecoder('utf-8', { fatal: true }).decode(merged);
330→        if (CONFLICT_MARKER.test(mergedText)) throw mergeError(`structured conflict markers remain in ${relativePath}`, 'structured_unresolved');
331→        let writePath; try { writePath = realpathSync(absolutePath); } catch { throw mergeError(`structured conflict path changed during resolution: ${relativePath}`, 'structured_unsupported_path'); }
332→        if (writePath !== realConflictPath) throw mergeError(`structured conflict path changed during resolution: ${relativePath}`, 'structured_unsupported_path');
333→        writeFileSync(absolutePath, merged, { mode: 0o600 });
334→        gitFile(['add', '--', relativePath], stagePath, { stdio: 'pipe' });
335→        classes.push({ path: relativePath, class: 'structured_resolved' });
336→      }
337→    }
338→    const remaining = gitFile(['diff', '--name-only', '--diff-filter=U', '-z'], stagePath, { encoding: 'utf8' });
339→    if (remaining.length > 0) throw mergeError('structured merge left unmerged index entries', 'structured_unresolved');
340→    try { gitFile(['diff', '--check', '--cached'], stagePath, { stdio: 'pipe' }); }
341→    catch (error) { throw mergeError('structured merge candidate fails git diff --check', 'structured_diff_invalid', error); }
342→    gitFile(['-c', 'core.hooksPath=/dev/null', 'commit', '--no-verify', '-q', '-m', `baton structured integration: ${taskId}`], stagePath, { stdio: 'pipe' },
343→      { GIT_AUTHOR_NAME: 'baton-merge', GIT_AUTHOR_EMAIL: 'baton-merge@localhost', GIT_COMMITTER_NAME: 'baton-merge', GIT_COMMITTER_EMAIL: 'baton-merge@localhost' });
344→    const stageSha = sh('git', ['rev-parse', 'HEAD'], stagePath);
345→    const parents = sh('git', ['show', '-s', '--format=%P', stageSha], stagePath).split(' ');
346→    if (parents.length !== 2 || parents[0] !== beforeSha || parents[1] !== rightSha) throw mergeError('structured candidate does not have the exact merge parents', 'structured_parent_mismatch');
347→    return Object.freeze({ taskId, beforeSha, resultSha: rightSha, mergeBaseSha, stageSha, stagePath, classes, resolutions, resolver: opts.resolver?.identity?.() ?? null });
348→  } catch (error) {
349→    await removeStructuredIntegration(repoRoot, { stagePath });
350→    if (error?.code?.startsWith('structured_')) throw error;
351→    throw mergeError(String(error?.message ?? error), 'structured_merge_failed', error);
352→  }
353→}
