23→// ---------------------------------------------------------------------------
24→// Errors (W7 — typed, never a bare Error wrapping raw stderr)
25→// ---------------------------------------------------------------------------
26→
27→export class DirtyRepoError extends Error {
28→  constructor(message) { super(message); this.name = 'DirtyRepoError'; }
29→}
30→export class BranchAlreadyCheckedOutError extends Error {
31→  constructor(message) { super(message); this.name = 'BranchAlreadyCheckedOutError'; }
32→}
