243→test('CK8/CK9: review task creation failure reaches no reviewer adapter and preserves parent evidence', async () => {
244→  const root = repo();
245→  commitBase(root);
246→  const implementer = familyAdapter('family-a', { outcome: 'completed', edits: [{ path: 'src/reviewed.txt', content: 'review me\n' }] });
247→  const reviewer = familyAdapter('family-b', { outcome: 'completed' });
248→  let reviewerSpawns = 0;
249→  const rawSpawn = reviewer.spawn.bind(reviewer);
250→  reviewer.spawn = async (...args) => { reviewerSpawns += 1; return rawSpawn(...args); };
251→  const driver = createDriver({ repoRoot: root, logDir: mkdtempSync(join(tmpdir(), 'baton-review-fault-log-')), adapters: { implementer, reviewer }, watchdog: { stallMs: 0 } });
252→  const parent = await driver.coordinator.spawn('implementer', brief({ command: 'test -f src/reviewed.txt', expectExit: 0 }), { taskId: 'review-fault-parent' });
253→  await until(async () => (await driver.coordinator.result(parent.id)).ready);
254→  const rawAppend = driver.coordination._appendFile;
255→  driver.coordination._appendFile = (file, body, encoding) => {
256→    if (body.includes('"task.created"') && body.includes('"review"')) throw new Error('review task disk full');
257→    return rawAppend(file, body, encoding);
258→  };
259→  await assert.rejects(driver.coordinator.spawnReview(parent.id, 'reviewer', {
260→    kind: 'review', taskId: 'review-fault-child', verification: { command: 'true', expectExit: 0 },
261→  }), (error) => error.code === 'coordination_write_unavailable');
262→  assert.equal(reviewerSpawns, 0);
263→  assert.deepEqual(driver.coordination.snapshot().tasks.map((task) => [task.id, task.status]), [['review-fault-parent', 'completed']]);
