266→test('AC5: ff-only integration reaps the worker/worktree/branch and records exact SHAs', async () => {
267→  const root = repo();
268→  commitBase(root, { 'README.md': 'base\n' });
269→  const beforeSha = git(['rev-parse', 'HEAD'], root);
270→  const { coordinator, coordination, log, handle, logDir } = await completedTask(root);
271→  const taskWorktree = coordinator.list().find((worker) => worker.id === handle.id)?.worktree;
272→  assert.equal(typeof taskWorktree, 'string');
273→
274→  const response = await coordinator.integrate(handle.id, { strategy: 'ff-only', actor: 'test-orchestrator' });
275→  assert.equal(response.ok, true);
276→  assert.equal(response.result, 'integrated');
277→  assert.equal(response.integration.beforeSha, beforeSha);
278→  assert.equal(response.integration.afterSha, response.integration.resultSha);
279→  assert.equal(git(['rev-parse', 'HEAD'], root), response.integration.resultSha);
280→  assert.equal(existsSync(join(root, 'src/integrated.txt')), true);
281→  assert.equal(coordinator.list().find((worker) => worker.id === handle.id)?.status, 'dead');
282→  assert.equal(existsSync(taskWorktree), false);
283→  assert.equal(git(['branch', '--list', 'baton/integrate-me'], root), '');
284→  assert.equal(git(['for-each-ref', '--format=%(refname)', `refs/baton/results/${response.integration.resultSha}`], root), '');
285→  assert.deepEqual((await coordinator.result(handle.id)).integration, response.integration);
286→  const event = log.read(handle.id).find((entry) => entry.kind === 'integration.completed');
